    beats = {
        { id = "dark", at = 15, title = "The dark",
            text = "I began in the dark, a striped seed no bigger than your fingernail. I didn't know what light was. I only knew which way was up, and that I wanted to go there very much." },
        { id = "first_morning", at = 40, title = "The first morning",
            text = "The day I broke through the soil, the sun was already waiting. Two small leaves, one enormous sky. I thought the sun had come out for me in particular. I have never fully let go of the idea." },
        { id = "following", at = 80, title = "Following",
            text = "When I was young I followed the sun from one wall to the other, every single day, and swung back east in the night so as not to miss the start. I was so afraid the light would leave without me." },
        { id = "planted", at = 140, title = "Who planted me",
            text = "I have never known who planted me. A finch may have dropped my seed, or a child, or the wind. Somebody carried me here, by accident or on purpose. I think about them at noon, when my shadow is shortest." },
        { id = "prairie", at = 220, title = "The prairie",
            text = "Sunflowers come from far to the west, from grassland wide as the sky. I have never seen that prairie. Yet on windy days I remember grass to the horizon, as if the memory came folded inside the seed." },
        { id = "storm", at = 320, title = "The storm",
            text = "One summer night a storm laid me almost flat. I couldn't run. Nobody with roots can. By morning I was bent like a question mark, and within the week I had grown straight again. I learned that about myself then." },
        { id = "stopped", at = 450, title = "The day I stopped turning",
            text = "A sunflower stops following the sun once the head is grown. One morning my neck simply held. I faced east and could turn no further. I thought: so this is all I will ever see. I was wrong about the all." },
        { id = "still", at = 600, title = "What comes to the still",
            text = "Since I couldn't go to the world, the world began coming to me. Bees first, glad of a face warm so early. Then finches. A hedgehog under my leaves at dusk. Standing still turned out to be a kind of invitation." },
        { id = "envy", at = 800, title = "A small envy",
            text = "I will tell you something unsunny. I have envied everyone with legs or wings. The fox goes where the fox likes. I have this one square of soil and the view over one wall. Some evenings that felt small." },
        { id = "first_book", at = 1050, title = "The first book",
            text = "Then you sat near me with a book, and went somewhere without leaving. I watched your face cross whole countries. So that is how the rooted travel, I thought. I have been travelling by your face ever since." },
        { id = "spirals", at = 1400, title = "The spirals",
            text = "Look at my face: every seed sits in a spiral, each a small turn on from the last, with room made for all. {total} pages we have read together. I like to think each one has a place in there." },
        { id = "east", at = 1800, title = "East",
            text = "I used to follow the sun for fear the light would leave. Then my turning stopped, and I faced the gate, and you came through. You keep coming through. I have a whole summer of seeds to give away, and the best thing I know is still this: I face one way, and you arrive." },
    },
